// Paths are drawn in a 400 x 240 viewBox: source at (50, 120), hub at (200, 120), targets at x 333
const SOURCE_PATH = "M50 120 H200";

const targets = [
  {
    label: "API",
    icon: Braces,
    path: "M200 120 H240 Q270 120 270 90 V70 Q270 40 300 40 H333",
    position: "top-1/6",
    iconClass: "bg-teal-400/15 text-teal-400",
    beamClass: "stroke-teal-400",
  },
  {
    label: "Database",
    icon: Database,
    path: "M200 120 H333",
    position: "top-1/2",
    iconClass: "bg-blue-500/15 text-blue-500",
    beamClass: "stroke-blue-500",
  },
  {
    label: "Deploy",
    icon: Rocket,
    path: "M200 120 H240 Q270 120 270 150 V170 Q270 200 300 200 H333",
    position: "top-5/6",
    iconClass: "bg-orange-400/15 text-orange-400",
    beamClass: "stroke-orange-400",
  },
];

const AnimatedBeamDesignToCode = () => {
  return (
    <div className="relative mx-auto aspect-5/3 w-full max-w-lg">
      {/* Connection lines with travelling light pulses */}
      <svg
        aria-hidden="true"
        viewBox="0 0 400 240"
        fill="none"
        className="absolute inset-0 size-full"
      >
        <path
          d={SOURCE_PATH}
          pathLength={100}
          strokeWidth={1.5}
          vectorEffect="non-scaling-stroke"
          className="stroke-border"
        />
        <path
          d={SOURCE_PATH}
          pathLength={100}
          strokeWidth={2}
          strokeLinecap="round"
          vectorEffect="non-scaling-stroke"
          className="animated-beam-02-pulse animated-beam-02-source stroke-sky-400"
        />
        {targets.map((target) => (
          <g key={target.label}>
            <path
              d={target.path}
              pathLength={100}
              strokeWidth={1.5}
              vectorEffect="non-scaling-stroke"
              className="stroke-border"
            />
            <path
              d={target.path}
              pathLength={100}
              strokeWidth={2}
              strokeLinecap="round"
              vectorEffect="non-scaling-stroke"
              className={cn(
                "animated-beam-02-pulse animated-beam-02-target",
                target.beamClass
              )}
            />
          </g>
        ))}
      </svg>

      {/* Figma source */}
      <div className="absolute top-1/2 left-1/8 flex size-14 -translate-x-1/2 -translate-y-1/2 items-center justify-center rounded-2xl border border-border bg-background">
        <FigmaIcon aria-hidden="true" className="h-7 w-5" />
        <span className="sr-only">Figma</span>
      </div>

      {/* Claude hub */}
      <div className="absolute top-1/2 left-1/2 -ml-3 flex size-16 -translate-x-1/2 -translate-y-1/2 items-center justify-center rounded-full border border-border bg-background">
        <ClaudeIcon aria-hidden="true" className="size-8" />
        <span className="sr-only">Claude</span>
      </div>

      {/* Targets */}
      {targets.map((target) => {
        const Icon = target.icon;
        return (
          <div
            key={target.label}
            className={cn(
              "absolute left-5/6 flex -translate-x-1/2 -translate-y-1/2 items-center gap-2 rounded-full border border-border bg-background py-1.5 ps-1.5 pe-3",
              target.position
            )}
          >
            <span
              className={cn(
                "flex size-7 items-center justify-center rounded-full",
                target.iconClass
              )}
            >
              <Icon aria-hidden="true" className="size-4" />
            </span>
            <span className="text-sm font-medium text-foreground">
              {target.label}
            </span>
          </div>
        );
      })}
    </div>
  );
};

export default AnimatedBeamDesignToCode;

.animated-beam-02-pulse {
  stroke-dasharray: 16 200;
  stroke-dashoffset: 16;
  animation-duration: 2.4s;
  animation-timing-function: linear;
  animation-iteration-count: infinite;
}

/* Left beam travels in the first part of the cycle and reaches the hub first */
.animated-beam-02-source {
  animation-name: animated-beam-02-flow-source;
}

/* Right beams leave the hub only after the left beam arrives */
.animated-beam-02-target {
  animation-name: animated-beam-02-flow-target;
}

@keyframes animated-beam-02-flow-source {
  0% {
    stroke-dashoffset: 16;
  }
  35%,
  100% {
    stroke-dashoffset: -100;
  }
}

@keyframes animated-beam-02-flow-target {
  0%,
  35% {
    stroke-dashoffset: 16;
  }
  100% {
    stroke-dashoffset: -100;
  }
}

@media (prefers-reduced-motion: reduce) {
  .animated-beam-02-pulse {
    animation: none;
    stroke-dasharray: none;
    opacity: 0.4;
  }
}
